-/*
- * Fused MoE finalize + shared-output add (bf16 output, SM>=90 for PDL).
- *
- * Forked from flashinfer's ``finalizeKernel`` and ``finalizeKernelVecLoad``
- * (trtllm_fused_moe_dev_kernel.cu:639 and :803), stripped of the MoE
- * backend's KernelParams / UsePdl templating, and extended with an
- * optional shared_output residual add on the epilogue side.
- *
- * For each token t, computes:
- *     out[t] = Σ_k expert_weights[t, k] * gemm2_out[permuted_idx(t, k)]
- *            + shared_output[t]                      // if non-null
- *
- * Eliminates the native PyTorch ``routed + shared_output`` add (and the
- * separate ``*= routed_scaling_factor`` kernel when applicable) from
- * ``DeepseekV3MoE.forward``, and gives the downstream allreduce+rmsnorm
- * a clean PDL handoff.
- *
- * Expert-weight dtype is templated on ``TypeExpW`` so we accept both bf16
- * and fp32 topk weights: the trtllm deferred finalize returns bf16 for packed
- * routing and the caller's own fp32 weights for unpacked routing.
- *
- * Expert-weight scale convention: in our target backends
- * (flashinfer trtllm nvfp4 + unquantized), ``apply_routed_scaling_factor_on_output``
- * is True, so the routed scaling factor is already folded into
- * ``expert_weights`` at topk time. This kernel does not apply any
- * additional scale.
- */
-
-#include <cutlass/array.h>
-#include <cutlass/numeric_conversion.h>
-#include <cutlass/numeric_types.h>
-
-#include "tvm_ffi_utils.h"
-#include <cuda_runtime.h>
-
-namespace sglang {
-
-using BF16 = cutlass::bfloat16_t;
-
-constexpr int FINALIZE_THREADS_PER_BLOCK = 256;
-constexpr int MAX_TOPK = 64;
-
-// ---------------------------------------------------------------------------
-// General kernel — one CTA per (hidden_chunk, token). Picks up small-to-mid
-// workloads where the block count fits in a few waves.
-// ---------------------------------------------------------------------------
-template <typename TypeExpW>
-__global__ void moeFinalizeKernel(
-    int numTokens,
-    int hiddenDim,
-    int hiddenDimPadded,
-    int topK,
-    BF16 const* __restrict__ inPtr,
-    int const* __restrict__ expandedIdxToPermutedIdx,
-    TypeExpW const* __restrict__ expertWeightsPtr,
-    BF16 const* __restrict__ sharedBiasPtr,
-    BF16* __restrict__ outPtr) {
-#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 900)
-  cudaGridDependencySynchronize();
-#endif
-
-  for (int64_t tokenIdx = blockIdx.y; tokenIdx < numTokens; tokenIdx += gridDim.y) {
-    for (int64_t hiddenIdx = threadIdx.x + blockDim.x * blockIdx.x; hiddenIdx < hiddenDim;
-         hiddenIdx += blockDim.x * gridDim.x) {
-      float acc = 0.0f;
-      for (int k = 0; k < topK; k++) {
-        int64_t const expandedIdx = tokenIdx * topK + k;
-        int64_t const permutedIdx = expandedIdxToPermutedIdx[expandedIdx];
-        if (permutedIdx == -1) {
-          continue;
-        }
-        float const scale = static_cast<float>(expertWeightsPtr[expandedIdx]);
-        float const val = static_cast<float>(inPtr[permutedIdx * hiddenDimPadded + hiddenIdx]);
-        acc += scale * val;
-      }
-      if (sharedBiasPtr != nullptr) {
-        acc += static_cast<float>(sharedBiasPtr[tokenIdx * hiddenDim + hiddenIdx]);
-      }
-      outPtr[tokenIdx * hiddenDim + hiddenIdx] = static_cast<BF16>(acc);
-    }
-  }
-
-#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 900)
-  cudaTriggerProgrammaticLaunchCompletion();
-#endif
-}
-
-// ---------------------------------------------------------------------------
-// Vectorized-load kernel — one CTA per token, 128-bit loads, topK unrolled.
-// Better at prefill shapes where the general kernel's block count saturates
-// many waves and the indirect gather from gemm2_out dominates.
-// ---------------------------------------------------------------------------
-
-__device__ inline float4 vectorizedLoadPtx(float4 const* ptr) {
-  float4 ret;
-  asm volatile("ld.global.v4.f32 {%0, %1, %2, %3}, [%4];"
-               : "=f"(ret.x), "=f"(ret.y), "=f"(ret.z), "=f"(ret.w)
-               : "l"(ptr));
-  return ret;
-}
-
-template <int TopKUnrollFactor>
-struct IdxPackedTraits;
-template <>
-struct IdxPackedTraits<1> {
-  using Packed = int;
-};
-template <>
-struct IdxPackedTraits<2> {
-  using Packed = int2;
-};
-template <>
-struct IdxPackedTraits<4> {
-  using Packed = int4;
-};
-
-template <typename TypeExpW, int TopKUnrollFactor>
-__global__ void moeFinalizeKernelVecLoad(
-    int numTokens,
-    int hiddenDim,
-    int hiddenDimPadded,
-    int topK,
-    BF16 const* __restrict__ inPtr,
-    int const* __restrict__ expandedIdxToPermutedIdx,
-    TypeExpW const* __restrict__ expertWeightsPtr,
-    BF16 const* __restrict__ sharedBiasPtr,
-    BF16* __restrict__ outPtr) {
-  static_assert(
-      TopKUnrollFactor == 1 || TopKUnrollFactor == 2 || TopKUnrollFactor == 4, "TopKUnrollFactor must be 1, 2, or 4");
-  using IdxPackedType = typename IdxPackedTraits<TopKUnrollFactor>::Packed;
-  using IdxArrayType = cutlass::Array<int, TopKUnrollFactor>;
-  using ScaleArrayType = cutlass::Array<TypeExpW, TopKUnrollFactor>;
-
-  // 128 bits per thread → 8 bf16 elements.
-  constexpr int FINALIZE_ELEM_PER_THREAD = 8;
-  using InputElem = cutlass::Array<BF16, FINALIZE_ELEM_PER_THREAD>;
-  using OutputElem = cutlass::Array<BF16, FINALIZE_ELEM_PER_THREAD>;
-  using ComputeElem = cutlass::Array<float, FINALIZE_ELEM_PER_THREAD>;
-
-  int64_t const tokenIdx = blockIdx.x;
-  int64_t const startOffset = threadIdx.x;
-  int64_t const stride = FINALIZE_THREADS_PER_BLOCK;
-  int64_t const numElemsInPaddedCol = hiddenDimPadded / FINALIZE_ELEM_PER_THREAD;
-  int64_t const numElemsInCol = hiddenDim / FINALIZE_ELEM_PER_THREAD;
-
-  // Stage the per-token (topK/unroll) indices + scales into smem.
-  __shared__ ScaleArrayType scaleArrSmem[MAX_TOPK / TopKUnrollFactor];
-  __shared__ IdxArrayType permutedIdxArrSmem[MAX_TOPK / TopKUnrollFactor];
-
-  for (int kChunkIdx = threadIdx.x; kChunkIdx < topK / TopKUnrollFactor; kChunkIdx += blockDim.x) {
-    int64_t const expandedIdx = tokenIdx * topK + kChunkIdx * TopKUnrollFactor;
-    auto const permutedIdxPacked =
-        reinterpret_cast<IdxPackedType const*>(expandedIdxToPermutedIdx)[expandedIdx / TopKUnrollFactor];
-    permutedIdxArrSmem[kChunkIdx] = *reinterpret_cast<IdxArrayType const*>(&permutedIdxPacked);
-#pragma unroll
-    for (int ki = 0; ki < TopKUnrollFactor; ++ki) {
-      scaleArrSmem[kChunkIdx][ki] = expertWeightsPtr[expandedIdx + ki];
-    }
-  }
-
-  BF16* outputPtr = outPtr + tokenIdx * hiddenDim;
-  auto* outElemPtr = reinterpret_cast<OutputElem*>(outputPtr);
-  auto const* inElemPtr = reinterpret_cast<InputElem const*>(inPtr);
-  auto const* sharedElemPtr =
-      sharedBiasPtr != nullptr ? reinterpret_cast<InputElem const*>(sharedBiasPtr + tokenIdx * hiddenDim) : nullptr;
-
-#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 900)
-  cudaGridDependencySynchronize();
-#endif
-  __syncthreads();
-
-  for (int elemIndex = startOffset; elemIndex < numElemsInCol; elemIndex += stride) {
-    ComputeElem threadOutput;
-    threadOutput.fill(0.0f);
-
-    for (int kChunkIdx = 0; kChunkIdx < topK / TopKUnrollFactor; kChunkIdx++) {
-      IdxArrayType permutedIdxArr = permutedIdxArrSmem[kChunkIdx];
-      InputElem inputElemArr[TopKUnrollFactor];
-#pragma unroll
-      for (int ki = 0; ki < TopKUnrollFactor; ++ki) {
-        int const permutedIdx = permutedIdxArr[ki];
-        if (permutedIdx == -1) {
-          continue;
-        }
-        auto const* inputPermutedPtr = inElemPtr + permutedIdx * numElemsInPaddedCol;
-        float4 input = vectorizedLoadPtx(reinterpret_cast<float4 const*>(&inputPermutedPtr[elemIndex]));
-        inputElemArr[ki] = *reinterpret_cast<InputElem const*>(&input);
-      }
-      ScaleArrayType scaleArr = scaleArrSmem[kChunkIdx];
-#pragma unroll
-      for (int ki = 0; ki < TopKUnrollFactor; ++ki) {
-        int const permutedIdx = permutedIdxArr[ki];
-        if (permutedIdx == -1) {
-          continue;
-        }
-        float const scale = static_cast<float>(scaleArr[ki]);
-        cutlass::NumericArrayConverter<float, BF16, FINALIZE_ELEM_PER_THREAD> toFloat;
-        ComputeElem expertResult = toFloat(inputElemArr[ki]);
-#pragma unroll
-        for (int e = 0; e < FINALIZE_ELEM_PER_THREAD; ++e) {
-          threadOutput[e] += scale * expertResult[e];
-        }
-      }
-    }
-
-    if (sharedElemPtr != nullptr) {
-      float4 shared = vectorizedLoadPtx(reinterpret_cast<float4 const*>(&sharedElemPtr[elemIndex]));
-      InputElem sharedElem = *reinterpret_cast<InputElem const*>(&shared);
-      cutlass::NumericArrayConverter<float, BF16, FINALIZE_ELEM_PER_THREAD> toFloat;
-      ComputeElem sharedFloat = toFloat(sharedElem);
-#pragma unroll
-      for (int e = 0; e < FINALIZE_ELEM_PER_THREAD; ++e) {
-        threadOutput[e] += sharedFloat[e];
-      }
-    }
-
-    cutlass::NumericArrayConverter<BF16, float, FINALIZE_ELEM_PER_THREAD> toBF16;
-    outElemPtr[elemIndex] = toBF16(threadOutput);
-  }
-
-#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 900)
-  cudaTriggerProgrammaticLaunchCompletion();
-#endif
-}
-
-// ---------------------------------------------------------------------------
-// Typed dispatch
-// ---------------------------------------------------------------------------
-template <typename TypeExpW>
-void dispatchFinalize(
-    int numTokens,
-    int hiddenDim,
-    int hiddenDimPadded,
-    int topK,
-    BF16 const* inPtr,
-    int const* expandedIdxPtr,
-    void const* weightsPtrVoid,
-    BF16 const* sharedPtr,
-    BF16* outPtr,
-    bool useVecLoad,
-    cudaStream_t stream,
-    cudaLaunchAttribute const* attrs,
-    int numAttrs) {
-  auto const* weightsPtr = static_cast<TypeExpW const*>(weightsPtrVoid);
-  constexpr int kNumThreads = 256;
-
-  if (!useVecLoad) {
-    int const numBlocksX = (hiddenDim + kNumThreads - 1) / kNumThreads;
-    int const numBlocksY = std::min(8192, numTokens);
-    cudaLaunchConfig_t config;
-    config.gridDim = dim3(numBlocksX, numBlocksY);
-    config.blockDim = dim3(kNumThreads);
-    config.dynamicSmemBytes = 0;
-    config.stream = stream;
-    config.numAttrs = numAttrs;
-    config.attrs = const_cast<cudaLaunchAttribute*>(attrs);
-
-    cudaLaunchKernelEx(
-        &config,
-        moeFinalizeKernel<TypeExpW>,
-        numTokens,
-        hiddenDim,
-        hiddenDimPadded,
-        topK,
-        inPtr,
-        expandedIdxPtr,
-        weightsPtr,
-        sharedPtr,
-        outPtr);
-    return;
-  }
-
-  auto launch = [&](auto unroll_tag) {
-    constexpr int UNROLL = decltype(unroll_tag)::value;
-    cudaLaunchConfig_t config;
-    config.gridDim = dim3(numTokens);
-    config.blockDim = dim3(FINALIZE_THREADS_PER_BLOCK);
-    config.dynamicSmemBytes = 0;
-    config.stream = stream;
-    config.numAttrs = numAttrs;
-    config.attrs = const_cast<cudaLaunchAttribute*>(attrs);
-    cudaLaunchKernelEx(
-        &config,
-        moeFinalizeKernelVecLoad<TypeExpW, UNROLL>,
-        numTokens,
-        hiddenDim,
-        hiddenDimPadded,
-        topK,
-        inPtr,
-        expandedIdxPtr,
-        weightsPtr,
-        sharedPtr,
-        outPtr);
-  };
-  // Match flashinfer's LAUNCH_TOPK_EXPW dispatch order.
-  if (topK % 4 == 0) {
-    launch(std::integral_constant<int, 4>{});
-  } else if (topK % 2 == 0) {
-    launch(std::integral_constant<int, 2>{});
-  } else {
-    launch(std::integral_constant<int, 1>{});
-  }
-}
-
-// ---------------------------------------------------------------------------
-// Host launcher
-// ---------------------------------------------------------------------------
-void moe_finalize_fuse_shared(
-    TensorView out,
-    TensorView gemm2_out,
-    TensorView expanded_idx_to_permuted_idx,
-    TensorView expert_weights,
-    TensorView shared_output,
-    int64_t top_k,
-    bool enable_pdl) {
-  TVM_FFI_ICHECK_EQ(out.ndim(), 2) << "out must be 2-D [numTokens, hiddenDim]";
-  TVM_FFI_ICHECK_EQ(gemm2_out.ndim(), 2) << "gemm2_out must be 2-D [totalNumPaddedTokens, hiddenDimPadded]";
-  TVM_FFI_ICHECK_EQ(expanded_idx_to_permuted_idx.ndim(), 1);
-  TVM_FFI_ICHECK_EQ(expert_weights.ndim(), 2) << "expert_weights must be 2-D [numTokens, topK]";
-
-  int const numTokens = int(out.size(0));
-  int const hiddenDim = int(out.size(1));
-  int const hiddenDimPadded = int(gemm2_out.size(1));
-  TVM_FFI_ICHECK_LE(top_k, MAX_TOPK);
-  TVM_FFI_ICHECK_EQ(expanded_idx_to_permuted_idx.size(0), numTokens * top_k);
-  TVM_FFI_ICHECK_EQ(expert_weights.size(0), numTokens);
-  TVM_FFI_ICHECK_EQ(expert_weights.size(1), top_k);
-
-  bool const hasShared = shared_output.numel() > 0;
-  if (hasShared) {
-    TVM_FFI_ICHECK_EQ(shared_output.ndim(), 2);
-    TVM_FFI_ICHECK_EQ(shared_output.size(0), numTokens);
-    TVM_FFI_ICHECK_EQ(shared_output.size(1), hiddenDim);
-  }
-
-  auto const* inPtr = static_cast<BF16 const*>(gemm2_out.data_ptr());
-  auto const* expandedIdxPtr = static_cast<int const*>(expanded_idx_to_permuted_idx.data_ptr());
-  auto const* sharedPtr = hasShared ? static_cast<BF16 const*>(shared_output.data_ptr()) : nullptr;
-  auto* outPtr = static_cast<BF16*>(out.data_ptr());
-
-  cudaSetDevice(out.device().device_id);
-  cudaStream_t const stream = get_stream(out.device());
-
-  // Dispatch heuristic (matches flashinfer): few waves → general kernel,
-  // many waves → vectorized. The 1184 threshold comes from 148 SMs × 8
-  // blocks/SM on Blackwell.
-  constexpr int kNumThreads = 256;
-  int const numBlocksX = (hiddenDim + kNumThreads - 1) / kNumThreads;
-  int const numBlocksY = std::min(8192, numTokens);
-  bool const useVecLoad = (numBlocksX * numBlocksY) >= 1184 && (hiddenDim % 8 == 0) && (hiddenDimPadded % 8 == 0);
-
-  cudaLaunchAttribute attrs[1];
-  attrs[0].id = cudaLaunchAttributeProgrammaticStreamSerialization;
-  attrs[0].val.programmaticStreamSerializationAllowed = enable_pdl;
-
-  auto ew_dtype = expert_weights.dtype();
-  if (ew_dtype == DLDataType{kDLFloat, 32, 1}) {
-    dispatchFinalize<float>(
-        numTokens,
-        hiddenDim,
-        hiddenDimPadded,
-        int(top_k),
-        inPtr,
-        expandedIdxPtr,
-        expert_weights.data_ptr(),
-        sharedPtr,
-        outPtr,
-        useVecLoad,
-        stream,
-        attrs,
-        1);
-  } else if (ew_dtype == DLDataType{kDLBfloat, 16, 1}) {
-    dispatchFinalize<BF16>(
-        numTokens,
-        hiddenDim,
-        hiddenDimPadded,
-        int(top_k),
-        inPtr,
-        expandedIdxPtr,
-        expert_weights.data_ptr(),
-        sharedPtr,
-        outPtr,
-        useVecLoad,
-        stream,
-        attrs,
-        1);
-  } else {
-    TVM_FFI_ICHECK(false) << "expert_weights dtype must be float32 or bfloat16";
-  }
-
-  cudaError_t const err = cudaGetLastError();
-  TVM_FFI_ICHECK(err == cudaSuccess) << "moe_finalize_fuse_shared launch failed: " << cudaGetErrorString(err);
-}
-
-TVM_FFI_DLL_EXPORT_TYPED_FUNC(moe_finalize_fuse_shared, moe_finalize_fuse_shared);
-
-}  // namespace sglang

@@ -0,0 +1,292 @@
+// Fused MoE finalize + shared-expert add for the deferred trtllm-gen MoE output:
+//   out[t] = sum_k w[t, k] * gemm2_out[permuted_idx[t * K + k]] (+ shared[t])
+// Rows whose permuted index is -1 are skipped; the fp32 accumulation runs in k
+// order with the shared row added last, the arithmetic of flashinfer's finalize.
+//
+// Each thread owns kVec hidden elements of a token and issues all K gathers at
+// once, so a token costs the index load plus one gather round trip. Tokens map
+// to blockIdx.y, which spreads even a single token over H / (kVec * kBlockSize)
+// CTAs. A token's route (K row indices and weights) is spread over the warp,
+// lane k holding slot k, so it costs two registers and the K gathers in flight
+// get the rest; that is what keeps a top-k 16 decode batch in one wave.
+// Past two resident waves a persistent variant walks several tokens per CTA,
+// loading the next token's route while the current gathers are in flight.
+
+#include <sgl_kernel/tensor.h>
+#include <sgl_kernel/utils.h>
+
+#include <sgl_kernel/math.cuh>
+#include <sgl_kernel/runtime.cuh>
+#include <sgl_kernel/type.cuh>
+#include <sgl_kernel/utils.cuh>
+#include <sgl_kernel/vec.cuh>
+
+#include <tvm/ffi/container/tensor.h>
+
+#include <algorithm>
+#include <cstddef>
+#include <cstdint>
+#include <type_traits>
+
+namespace sglang {
+
+namespace device::moe_finalize {
+
+inline constexpr uint32_t kBlockSize = 128;
+
+namespace ptx {
+
+// One slot's gather: zero the registers and load them under the predicate in a single asm. A skipped
+// slot (index -1, weight -0.0) then adds -0.0 * 0, which leaves the sum bitwise unchanged, and costs no
+// extra registers (a C++ conditional load makes ptxas keep a second copy of every vector). The asm is
+// volatile so that the K gathers of a token stay ahead of the FMAs.
+template <std::size_t kWords>
+SGL_DEVICE void ld_global_or_zero(void* dst, const void* ptr, bool valid) {
+  const auto r = static_cast<uint32_t*>(dst);
+  const auto pred = static_cast<uint32_t>(valid);
+  if constexpr (kWords == 4) {
+    asm volatile(
+        "{\n\t.reg .pred p;\n\tsetp.ne.b32 p, %5, 0;\n\tmov.b32 %0, 0;\n\tmov.b32 %1, 0;\n\t"
+        "mov.b32 %2, 0;\n\tmov.b32 %3, 0;\n\t@p ld.global.v4.u32 {%0, %1, %2, %3}, [%4];\n\t}"
+        : "=r"(r[0]), "=r"(r[1]), "=r"(r[2]), "=r"(r[3])
+        : "l"(ptr), "r"(pred));
+  } else if constexpr (kWords == 2) {
+    asm volatile(
+        "{\n\t.reg .pred p;\n\tsetp.ne.b32 p, %3, 0;\n\tmov.b32 %0, 0;\n\tmov.b32 %1, 0;\n\t"
+        "@p ld.global.v2.u32 {%0, %1}, [%2];\n\t}"
+        : "=r"(r[0]), "=r"(r[1])
+        : "l"(ptr), "r"(pred));
+  } else {
+    static_assert(kWords == 1);
+    asm volatile("{\n\t.reg .pred p;\n\tsetp.ne.b32 p, %2, 0;\n\tmov.b32 %0, 0;\n\t@p ld.global.u32 %0, [%1];\n\t}"
+                 : "=r"(r[0])
+                 : "l"(ptr), "r"(pred));
+  }
+}
+
+}  // namespace ptx
+
+struct Params {
+  const bf16_t* __restrict__ gemm2_out;
+  const int32_t* __restrict__ permuted_idx;
+  const void* __restrict__ expert_weights;
+  const bf16_t* __restrict__ shared;
+  bf16_t* __restrict__ out;
+  int64_t out_stride;     // elements per output row
+  uint32_t gemm2_stride;  // elements per gemm2_out row
+  uint32_t num_tokens;
+  uint32_t num_chunks;     // hidden size / kVec
+  bool route_before_wait;  // see MoeFinalizeKernel
+};
+
+template <typename TW, uint32_t K, uint32_t kVec, bool kHasShared>
+struct Token {
+  using wbits_t = std::conditional_t<sizeof(TW) == 2, uint16_t, uint32_t>;
+  // -0.0 of the weight type
+  static constexpr uint32_t kNegZero = sizeof(TW) == 2 ? 0x8000u : 0x80000000u;
+
+  int32_t row;      // lane k < K: permuted row of slot k
+  uint32_t weight;  // lane k < K: bits of the weight of slot k in its own type, -0.0 for a skipped slot
+  AlignedVector<bf16x2_t, kVec / 2> shared;
+
+  SGL_DEVICE void load(const Params& p, const uint32_t token, const uint32_t chunk, const uint32_t lane_id) {
+    load_shared(p, token, chunk);
+    load_route(p, token, lane_id);
+  }
+
+  SGL_DEVICE void load_shared(const Params& p, const uint32_t token, const uint32_t chunk) {
+    if constexpr (kHasShared) shared.load(p.shared + token * (int64_t{p.num_chunks} * kVec), chunk);
+  }
+
+  SGL_DEVICE void load_route(const Params& p, const uint32_t token, const uint32_t lane_id) {
+    row = -1;
+    weight = 0;
+    if (lane_id < K) {
+      // both loads unconditional: a weight load guarded by the row waits for it
+      row = p.permuted_idx[token * K + lane_id];
+      weight = static_cast<const wbits_t*>(p.expert_weights)[token * K + lane_id];
+      if (row == -1) weight = kNegZero;
+    }
+  }
+};
+
+// kPersistent: the grid holds one resident wave and each CTA walks tokens with
+// stride gridDim.y, prefetching the next token's route; otherwise every token
+// has its own CTA row and the body runs once (the launcher picks it only while
+// the grid fits one wave).
+// route_before_wait: the caller guarantees that the route was complete when
+// this kernel launched, so it loads before the PDL wait. The shared row always
+// loads after the wait: in a CUDA graph, its cross-stream join is a PDL edge too.
+template <typename TW, uint32_t K, uint32_t kVec, bool kPersistent, bool kHasShared, bool kUsePDL>
+__global__ __launch_bounds__(kBlockSize, 1) void finalize_kernel(const __grid_constant__ Params p) {
+  static_assert(K <= 32, "the route is spread over one warp");
+  constexpr uint32_t kPairs = kVec / 2;
+  using pairs_t = AlignedVector<bf16x2_t, kPairs>;
+  using token_t = Token<TW, K, kVec, kHasShared>;
+  const uint32_t lane_id = threadIdx.x % 32;
+  const uint32_t chunk = blockIdx.x * kBlockSize + threadIdx.x;
+  // Lanes past the row compute on its last chunk and skip the store, so that
+  // every lane of the warp takes part in the shuffles.
+  const uint32_t safe_chunk = std::min(chunk, p.num_chunks - 1);
+  const uint32_t col = safe_chunk * kVec;
+
+  if (!p.route_before_wait) PDLWaitPrimary<kUsePDL>();
+  uint32_t token = blockIdx.y;
+  token_t cur;
+  cur.load_route(p, token, lane_id);
+  if (p.route_before_wait) PDLWaitPrimary<kUsePDL>();
+  cur.load_shared(p, token, safe_chunk);
+  do {
+    pairs_t in[K];
+#pragma unroll
+    for (uint32_t k = 0; k < K; ++k) {
+      const int32_t row = __shfl_sync(0xffffffffu, cur.row, k);
+      const auto src = p.gemm2_out + static_cast<uint32_t>(max(row, 0)) * p.gemm2_stride + col;
+      ptx::ld_global_or_zero<kPairs>(&in[k], src, row != -1);
+    }
+    asm volatile("" ::: "memory");  // next-token loads go after the gathers (as measured)
+    const uint32_t next = token + gridDim.y;
+    token_t next_token;
+    if constexpr (kPersistent) {
+      if (next < p.num_tokens) next_token.load(p, next, safe_chunk, lane_id);
+    }
+
+    fp32x2_t acc[kPairs];
+#pragma unroll
+    for (uint32_t e = 0; e < kPairs; ++e) {
+      acc[e] = {0.0f, 0.0f};
+    }
+#pragma unroll
+    for (uint32_t k = 0; k < K; ++k) {
+      const uint32_t w_bits = __shfl_sync(0xffffffffu, cur.weight, k);
+      if constexpr (std::is_same_v<TW, bf16_t>) {
+        // mixed-precision FMA: bf16 x bf16 is exact in fp32, so this is the fp32 FMA bit for bit
+        const auto w = __ushort_as_bfloat16(static_cast<uint16_t>(w_bits));
+#pragma unroll
+        for (uint32_t e = 0; e < kPairs; ++e) {
+          acc[e].x = math::fma_f32_bf16(in[k][e].x, w, acc[e].x);
+          acc[e].y = math::fma_f32_bf16(in[k][e].y, w, acc[e].y);
+        }
+      } else {
+        const auto w = __uint_as_float(w_bits);
+#pragma unroll
+        for (uint32_t e = 0; e < kPairs; ++e) {
+          acc[e] = math::fma_f32x2({w, w}, cast<fp32x2_t>(in[k][e]), acc[e]);
+        }
+      }
+    }
+    pairs_t out;
+#pragma unroll
+    for (uint32_t e = 0; e < kPairs; ++e) {
+      if constexpr (kHasShared) {
+        const auto sh = cast<fp32x2_t>(cur.shared[e]);
+        acc[e].x += sh.x;
+        acc[e].y += sh.y;
+      }
+      out[e] = cast<bf16x2_t>(acc[e]);
+    }
+    if (chunk < p.num_chunks) out.store(p.out + token * p.out_stride, chunk);
+
+    if constexpr (kPersistent) {
+      if (next >= p.num_tokens) break;
+      token = next;
+      cur = next_token;
+    }
+  } while (kPersistent);
+  PDLTriggerSecondary<kUsePDL>();
+}
